PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?dir ?dirLabel ?birthDate WHERE {
  VALUES ?film { dbr:The_First_Day_of_Freedom dbr:Malabimba_-_The_Malicious_Whore }
  ?film dbo:director ?dir .
  OPTIONAL { ?dir dbo:birthDate ?bd1 . }
  OPTIONAL { ?dir dbp:birthDate ?bd2 . }
  OPTIONAL { ?dir dbp:born ?bd3 . }
  OPTIONAL { ?dir dbp:birth_date ?bd4 . }
  BIND(COALESCE(?bd1, ?bd2, ?bd3, ?bd4) AS ?birthDate)
  OPTIONAL { ?dir rdfs:label ?dirLabel . FILTER(lang(?dirLabel) = "en") }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
}
ORDER BY DESC(?birthDate)
LIMIT 1

